import clsx from 'clsx';
import React, { ElementType, ReactElement, forwardRef } from 'react';
import styled from 'styled-components';

import type { DataTestId } from '../../core/types/data-props.js';
import type { PolymorphicComponentProps } from '../../core/types/polymorph.js';
import type { StylingProps } from '../../core/types/styling-props.js';
import type { WithChildren } from '../../core/types/with-children.js';

/**
 * @deprecated `Column` component will be removed, use `Flex` or `Grid` instead.
 */
export interface ColumnItemProps extends StylingProps, DataTestId {
  /** Width of the column, which can either be set to spread the whole content, or to a predefined column fraction. */
  width?: ColumnWidthFractions;
}

/**
 * @deprecated `Column` component will be removed, use `Flex` or `Grid` instead.
 */
export type ColumnWidthFractions =
  | 'content'
  | '1/2'
  | '1/3'
  | '1/4'
  | '1/5'
  | '2/3'
  | '3/4'
  | '2/5'
  | '3/5'
  | '4/5';

/** Props used for the Column component, which consist of ColumnItemProps and children.
 * @deprecated `Column` component will be removed, use `Flex` or `Grid` instead.
 */
export interface ColumnOwnProps extends WithChildren, ColumnItemProps {}

// Merge own props with others inherited from the underlying element type
/**
 * @deprecated `Column` component will be removed, use `Flex` or `Grid` instead.
 */
export type ColumnProps<E extends ElementType> = PolymorphicComponentProps<
  E,
  ColumnOwnProps
>;

const StyledColumn = /* @__PURE__ */ styled('div')({
  flex: '1 0 auto',

  '&.column-fraction-content': {
    flex: '0 0 auto',
  },

  '&.column-fraction-1-2': {
    flex: '0 0 50%',
  },

  '&.column-fraction-1-3': {
    flex: '0 0 33.333%',
  },

  '&.column-fraction-1-4': {
    flex: '0 0 25%',
  },

  '&.column-fraction-1-5': {
    flex: '0 0 20%',
  },

  '&.column-fraction-2-3': {
    flex: '0 0 66.666%',
  },

  '&.column-fraction-3-4': {
    flex: '0 0 75%',
  },

  '&.column-fraction-2-5': {
    flex: '0 0 40%',
  },

  '&.column-fraction-3-5': {
    flex: '0 0 60%',
  },

  '&.column-fraction-4-5': {
    flex: '0 0 80%',
  },
});

/**
 * Column component
 * can be used with the columns component to create a simple layout.
 * @deprecated `Column` component will be removed, use `Flex` or `Grid` instead.
 */
export const Column: <E extends ElementType = 'div'>(
  props: ColumnProps<E>,
) => ReactElement | null = /* @__PURE__ */ forwardRef(
  <E extends ElementType>(
    props: ColumnProps<E>,
    forwardedRef: typeof props.ref,
  ) => {
    const {
      children,
      width,
      className: consumerClassName,
      style: consumerStyle,
      'data-testid': dataTestId,
      ...remainingProps
    }: ColumnProps<E> = props;

    return (
      <StyledColumn
        className={clsx(
          {
            'column-fraction-1-2': width === '1/2',
            'column-fraction-1-3': width === '1/3',
            'column-fraction-1-4': width === '1/4',
            'column-fraction-1-5': width === '1/5',
            'column-fraction-2-3': width === '2/3',
            'column-fraction-3-4': width === '3/4',
            'column-fraction-2-5': width === '2/5',
            'column-fraction-3-5': width === '3/5',
            'column-fraction-4-5': width === '4/5',
            'column-fraction-content': width === 'content',
          },
          consumerClassName,
        )}
        style={consumerStyle}
        {...remainingProps}
        ref={forwardedRef}
        data-testid={dataTestId}
      >
        {children}
      </StyledColumn>
    );
  },
);
